import{_ as a,c as t,o as n,ag as r}from"./chunks/framework.Vyheyqg9.js";const h=JSON.parse('{"title":"A Versioned Evaluation Lab for the Document Assistant — practice","description":"","frontmatter":{},"headers":[],"relativePath":"practice/applied-ai/chapters/evaluation-lab.md","filePath":"practice/applied-ai/chapters/evaluation-lab.md"}'),i={name:"practice/applied-ai/chapters/evaluation-lab.md"};function s(o,e,c,l,d,p){return n(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="a-versioned-evaluation-lab-for-the-document-assistant-—-practice" tabindex="-1">A Versioned Evaluation Lab for the Document Assistant — practice <a class="header-anchor" href="#a-versioned-evaluation-lab-for-the-document-assistant-—-practice" aria-label="Permalink to “A Versioned Evaluation Lab for the Document Assistant — practice”">​</a></h1><p><strong>Learner status: still required.</strong> These requirements were separated from the textbook. Use the <a href="./../">integrated sequence</a> and shared evidence record; running reference checks is not independent completion.</p><p><a href="./../../../python-for-ai/evaluation-lab.html">Textbook</a></p><h2 id="practice-and-acceptance" tabindex="-1"><span class="hub-section-number">1 </span>Practice and acceptance <a class="header-anchor" href="#practice-and-acceptance" aria-label="Permalink to “1 Practice and acceptance”">​</a></h2><p>Strict-typecheck and test the loader against the exact manifest: all six slices, unique IDs, stable exact-byte digest, wrong version, unknown/extra fields, missing slice, malformed/coerced labels, blank questions, answer-without-text, nonanswer-with-text, invalid Unicode and byte cap. These are dataset-format checks only. Review labels/source ledger with another reader and expand distribution/splits before using it to choose a model.</p><p>Wire the source fixture adapters through the real tool/provenance/answer gates. For ordinary/injected/Unicode cases require the supported intended answer with valid citation; missing evidence abstains, foreign access stays denied without hidden content and store failure remains operational. Add at least one deliberate validator/ACL/budget mutation and show the corresponding test fails. Record result categories even when a provider call never happens. A local synthetic output fixture cannot prove that a model handles the attack or language correctly.</p><p><strong>Material acceptance for25.01–25.05:</strong> clear task success and failure categories, a versioned bounded manifest and source/label ledger, representative-set limitations, edge/adversarial outcome criteria and executable deterministic validation. Real representative collection/label review, split leakage analysis, live model runs and independent learner implementation remain required. Later sections expand semantic/rubric/regression/cost analysis; do not treat this six-case fixture as final evaluation coverage.</p><p><strong>Acceptance:</strong> strict-typecheck and test exact recall/MRR/nDCG calculation, ideal/poor ordering, one/many/no hits, empty ranking, no-relevant labels, duplicate IDs, invalid/bool k/grades, ID bounds and graded ties. Rerun actual evidence/pipeline tests for stale/foreign/unknown/duplicate/misquoted citations, malformed outputs, correct abstention and a mechanically valid contradiction. Retain a claim-level support/correctness rubric with examples of partial support, omitted negation and outdated source. Then measure a labeled real retrieval set and answer outputs; synthetic metric arithmetic cannot establish system quality. Learner corpus judgments, semantic/human evaluation and live retrieval/provider comparison remain required.</p><p><strong>Acceptance:</strong> test compare_judge exact counts, all-accept/all-reject, missing/extra IDs, non-bool labels and empty bounds; test repeated-success all/none/mixed outcomes and invalid data. Review the worked two-part cancellation task with the0–2 anchors and adjudicate one disagreement using source evidence. Rerun actual tool/approval/graph state cases for argument/authorization/receipt correctness. Before a real judge gates releases, retain held-out human comparisons and position/length/language/injection bias checks; simulated arithmetic does not establish judge quality. Independent ratings, live repeated provider runs, calibrated semantic judge and learner evaluation practice remain required.</p>',9)])])}const m=a(i,[["render",s]]);export{h as __pageData,m as default};
